    #[test]
    fn simd_intrinsics() {
        // Warm every probe before the measured pass so asynchronous O3 builds
        // can finish while the other probes run. The printed hashes stay stable.
        simd_hashes(false);
        simd_hashes_x512(false);
        simd_hashes(true);
        simd_hashes_x512(true);
    simd_hashes_gen2(true);
        simd_hashes_mask0(false); simd_hashes_mask1(false); simd_hashes_mask2(false); simd_hashes_mask3(false); simd_hashes_mask4(false); simd_hashes_mask5b1(false); simd_hashes_mask5b2(false); 
        simd_hashes_mask0(true); simd_hashes_mask1(true); simd_hashes_mask2(true); simd_hashes_mask3(true); simd_hashes_mask4(true); simd_hashes_mask5b1(true); simd_hashes_mask5b2(true); simd_hashes_misc(true);
    }

